        dot=sum(a*b for a,b in zip(gfd,gA))
        cn=dot/(math.sqrt(sum(a*a for a in gfd))*math.sqrt(sum(g*g for g in gA)))
        out.append((h,num/den,cn))
    best=min(out,key=lambda t:t[1])
    print(f"lam={lam:<6} kappa={kap:<8g} best h={best[0]:.0e} relerr={best[1]:.2e} cos={best[2]:.10f}")
    for h,re_,cn in out: print(f"    h={h:.0e} relerr={re_:.2e} cos={cn:.10f}")
for lam in (1.0,0.1):
    for kap in (10.0, 1e6):
